/**
 * Shared section builders for agent briefing documents.
 *
 * Both the implementation briefing (agent-context.ts) and the review briefing
 * (reviewer-briefing.ts) share the same preamble, identity, and task-context
 * sections. Centralising them here ensures the two briefing types stay in sync.
 */

export interface TaskContextFields {
  taskId: string;
  featureId: string;
  taskTitle: string;
  taskBranch: string;
  taskRepo: string;
  taskRepoRoot: string;
  workspaceRoot: string;
  /** PR URL — only present for review briefings. */
  prUrl?: string;
}

export interface IdentityFields {
  gitAuthorEmail: string;
  gitAuthorName: string;
}

/** Standard automated-agent preamble (no interactive session). */
export function preambleSection(): string[] {
  return [
    "You are an automated software agent running in a headless container.",
    "There is no interactive session. Do not prompt for input.",
    "Do not ask clarifying questions. Execute the task described below.",
  ];
}

/** ## Identity section. */
export function identitySection(fields: IdentityFields): string[] {
  return [
    "## Identity",
    "",
    `Email: ${fields.gitAuthorEmail}`,
    `Name:  ${fields.gitAuthorName}`,
  ];
}

/** ## Your assigned task / Your claimed task section. */
export function taskContextSection(heading: string, fields: TaskContextFields): string[] {
  const lines = [
    `## ${heading}`,
    "",
    `Workspace root: ${fields.workspaceRoot}`,
    `Feature:        ${fields.featureId}`,
    `Task ID:        ${fields.taskId}`,
    `Title:          ${fields.taskTitle}`,
    `Impl repo:      ${fields.taskRepo}`,
    `Repo root:      ${fields.taskRepoRoot}`,
    `Branch:         ${fields.taskBranch}`,
  ];
  if (fields.prUrl !== undefined) {
    lines.push(`PR URL:         ${fields.prUrl}`);
  }
  return lines;
}

/** ## Model section. */
export function modelSection(implementationModel: string): string[] {
  return ["## Model", "", `Use model: ${implementationModel}`];
}

/**
 * Join section arrays with blank lines between them, ending with a trailing newline.
 */
export function joinSections(...sections: string[][]): string {
  return sections.map((s) => s.join("\n")).join("\n\n");
}

