/**
 * Briefing generator for the Claude impl executor.
 *
 * Reads task context from the already-cloned management repo (mgmtDir) rather
 * than receiving pre-built content from the orchestrator. The executor is
 * fully self-contained: given TASK_ID, FEATURE_ID, and the cloned mgmt repo,
 * it constructs its own prompt without any orchestrator-owned briefing logic.
 */

import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import {
  preambleSection,
  identitySection,
  taskContextSection,
  modelSection,
  joinSections,
} from "./briefing-template.js";

export interface ImplBriefingOpts {
  taskId: string;
  featureId: string;
  taskBranch: string;
  taskRepo: string;
  taskRepoRoot: string;
  workspaceRoot: string;
  gitAuthorEmail: string;
  gitAuthorName: string;
  implementationModel: string;
  resultPath: string;
}

/**
 * Read the task title from the task YAML in the cloned mgmt repo.
 * Falls back to taskId if the YAML cannot be read.
 */
function readTaskTitle(mgmtDir: string, featureId: string, taskId: string): string {
  try {
    const yamlPath = join(mgmtDir, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
    const raw = readFileSync(yamlPath, "utf-8");
    const task = parseYaml(raw) as Record<string, unknown>;
    return typeof task["title"] === "string" ? task["title"] : taskId;
  } catch {
    return taskId;
  }
}

/**
 * Read handover.md from the task working directory if present.
 * Returns the formatted section string, or undefined if no handover exists.
 */
function readHandoverSection(taskRepoRoot: string): string | undefined {
  const handoverPath = join(taskRepoRoot, "handover.md");
  if (!existsSync(handoverPath)) return undefined;

  try {
    const content = readFileSync(handoverPath, "utf-8").trim();
    if (!content) return undefined;
    return `## Continuing previous run\n\n${content}`;
  } catch {
    return undefined;
  }
}

function checkpointDisciplineSection(taskId: string, resultPath: string): string[] {
  return [
    "## Checkpoint discipline",
    "",
    "After each substantial action (file write, test run, multi-file edit), commit",
    "and push your work-in-progress to the feature branch with a",
    `\`wip(${taskId}): <what you just did>\` message. Do NOT batch many actions into`,
    "a single commit. This protects against unexpected termination.",
    "",
    "If you sense you have done many back-and-forth turns and are not yet ready to",
    "declare the work complete, perform a graceful checkpoint:",
    "",
    "1. Commit and push any uncommitted work.",
    "2. Open the impl PR as draft via `/pr-create` if not already open.",
    "3. Write `handover.md` next to the result file describing: what is done, what is",
    "   left, where to resume. Write it as if you are briefing the next engineer.",
    `4. Write \`${resultPath}\` with:`,
    '   `{"terminal_status": "blocked", "blocked_reason": "handover_for_continuation",',
    '    "pr_url": "<PR URL>", "handover_path": "<path to handover.md>"}`',
    "5. Exit cleanly.",
    "",
    "Layer 1 (post-hoc recovery) will commit+push+open a draft PR automatically if",
    "you exit without writing a result file — but a graceful checkpoint you write is",
    "richer and more useful for the next agent.",
  ];
}

/**
 * Generate the per-activation briefing markdown for the Claude impl executor.
 *
 * Reads task title from the cloned mgmt repo. All other context is derived
 * from env vars already resolved by the executor before calling this function.
 *
 * Sections (in order):
 *   0. Continuing previous run (Layer 3) — prepended only when handover.md exists
 *   1. Preamble — automated context, no interactive session
 *   2. ## Identity
 *   3. ## Your assigned task
 *   4. ## What you must do
 *   5. ## Model
 *   6. ## Rules
 *   7. ## Checkpoint discipline (Layer 2)
 */
export function generateBriefing(mgmtDir: string, opts: ImplBriefingOpts): string {
  const {
    taskId,
    featureId,
    taskBranch,
    taskRepo,
    taskRepoRoot,
    workspaceRoot,
    gitAuthorEmail,
    gitAuthorName,
    implementationModel,
    resultPath,
  } = opts;

  const taskTitle = readTaskTitle(mgmtDir, featureId, taskId);
  const handoverSection = readHandoverSection(taskRepoRoot);

  const coreSections = joinSections(
    preambleSection(),
    identitySection({ gitAuthorEmail, gitAuthorName }),
    taskContextSection("Your assigned task", {
      taskId, featureId, taskTitle, taskBranch,
      taskRepo, taskRepoRoot, workspaceRoot,
    }),
    [
      "## What you must do",
      "",
      `Run \`/start-implementation ${taskId}\``,
      "",
      "The skill handles the full execution contract: implement (including unit tests) →",
      "self-review → execute the test plan from tasks.md → open the impl PR → post test",
      `plan results as PR comment → write \`result.json\` to \`${resultPath}\`.`,
      "",
      "Complete all steps without stopping or asking for confirmation.",
    ],
    modelSection(implementationModel),
    [
      "## Rules",
      "",
      "- Do not ask clarifying questions. Implement what is specified.",
      "- Do not modify task YAML files or any management-repo workflow state.",
      `- The \`/start-implementation\` skill writes \`${resultPath}\` automatically (Step 5, agent-runtime).`,
      "  If the skill cannot complete, the orchestrator's post-hoc recovery writes a blocked result.",
      "- If a shell command exits with code 127 (command not found), immediately write",
      `  \`{"terminal_status": "blocked", "blocked_reason": "missing_tool"}\` to \`${resultPath}\` and exit.`,
      "  Do not attempt workarounds — this is a container image problem.",
    ],
    checkpointDisciplineSection(taskId, resultPath),
  );

  if (handoverSection) {
    return handoverSection + "\n\n---\n\n" + coreSections;
  }
  return coreSections;
}

