/**
 * Briefing generator for the fix agent executor.
 *
 * Reads task context from the already-cloned management repo (mgmtDir).
 * Instructs the executor to run /respond-to-review to address all
 * REQUEST_CHANGES review comments on the implementation PR.
 */

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { parse as parseYaml } from "yaml";
import {
  preambleSection,
  identitySection,
  taskContextSection,
  modelSection,
  joinSections,
} from "./briefing-template.js";

export interface FixBriefingOpts {
  taskId: string;
  featureId: string;
  taskBranch: string;
  taskRepo: string;
  taskRepoRoot: string;
  workspaceRoot: string;
  prUrl: string;
  gitAuthorEmail: string;
  gitAuthorName: string;
  implementationModel: string;
  resultPath: string;
}

function readTaskTitle(mgmtDir: string, featureId: string, taskId: string): string {
  try {
    const yamlPath = join(mgmtDir, "docs", "features", featureId, "tasks", `${taskId}.yaml`);
    const raw = readFileSync(yamlPath, "utf-8");
    const task = parseYaml(raw) as Record<string, unknown>;
    return typeof task["title"] === "string" ? task["title"] : taskId;
  } catch {
    return taskId;
  }
}

/**
 * Generate the per-activation briefing markdown for the fix agent executor.
 *
 * Sections (in order):
 *   1. Preamble — automated context, no interactive session
 *   2. ## Identity
 *   3. ## Your claimed task
 *   4. ## What you must do
 *   5. ## Model
 *   6. ## Rules
 */
export function generateFixBriefing(mgmtDir: string, opts: FixBriefingOpts): string {
  const {
    taskId,
    featureId,
    taskBranch,
    taskRepo,
    taskRepoRoot,
    workspaceRoot,
    prUrl,
    gitAuthorEmail,
    gitAuthorName,
    implementationModel,
    resultPath,
  } = opts;

  const taskTitle = readTaskTitle(mgmtDir, featureId, taskId);

  return joinSections(
    preambleSection(),
    identitySection({ gitAuthorEmail, gitAuthorName }),
    taskContextSection("Your claimed task", {
      taskId,
      featureId,
      taskTitle,
      taskBranch,
      taskRepo,
      taskRepoRoot,
      workspaceRoot,
      prUrl,
    }),
    [
      "## What you must do",
      "",
      `Run \`/respond-to-review\` to address all open REQUEST_CHANGES review comments on the PR at \`${prUrl}\`.`,
      "",
      "The skill handles the full fix contract:",
      "  1. Set the PR to draft.",
      "  2. Fetch all unresolved inline review threads from the PR.",
      "  3. Check out the implementation branch and address each comment in code.",
      "  4. Push the fix commits.",
      "  5. Resolve each inline thread via GitHub GraphQL API.",
      "  6. Convert the PR back to ready-for-review.",
      "  7. Write a comments_addressed log entry in the task YAML.",
      "",
      "After the skill completes, write `result.json` to `" + resultPath + "` with:",
      '  `{"terminal_status": "in_review", "pr_url": "' + prUrl + '"}`',
      "",
      "Complete all steps without stopping or asking for confirmation.",
    ],
    modelSection(implementationModel),
    [
      "## Rules",
      "",
      "- Do not ask clarifying questions.",
      "- Use `GITHUB_TOKEN` from the environment for all GitHub API calls.",
      "- Read the product spec, technical design, and tasks.md before making any code changes.",
      "- Only address comments that fall within the task scope defined by tasks.md.",
      "- If a review comment contradicts the approved spec, note the conflict and do not implement it.",
      "- After /respond-to-review completes successfully, write result.json as the final step.",
      `- Always write \`${resultPath}\` — even if an individual step fails.`,
      "- If a shell command exits with code 127 (command not found), immediately write",
      `  \`{"terminal_status": "blocked", "blocked_reason": "missing_tool"}\` to \`${resultPath}\` and exit.`,
      "  Do not attempt workarounds — this is a container image problem.",
      "- On success write:",
      `  \`{"terminal_status": "in_review", "pr_url": "${prUrl}"}\``,
      "- On failure (push rejected, GraphQL error, etc.) write:",
      `  \`{"terminal_status": "blocked", "blocked_reason": "<reason>", "pr_url": "${prUrl}"}\``,
    ],
  );
}

